Solution B: function createSortingVisualizer(canvasId){const canvas=document.getElementById(canvasId);if(!canvas){throw new Error("Canvas not found");}canvas.width=500;canvas.height=500;const ctx=canvas.getContext("2d");const UI=document.createElement("div");UI.style.marginTop="10px";document.body.appendChild(UI);const algoSelect=document.createElement("select");["Bubble","Quick","Merge","Heap","Radix"].forEach(a=>{const o=document.createElement("option");o.value=a;o.textContent=a;algoSelect.appendChild(o);});UI.appendChild(algoSelect);UI.appendChild(document.createTextNode(" Speed: "));const speedSlider=document.createElement("input");speedSlider.type="range";speedSlider.min="10";speedSlider.max="200";speedSlider.value="60";UI.appendChild(speedSlider);const speedLabel=document.createElement("span");speedLabel.textContent="60ms";UI.appendChild(speedLabel);UI.appendChild(document.createTextNode(" Step-by-step: "));const stepCheckbox=document.createElement("input");stepCheckbox.type="checkbox";UI.appendChild(stepCheckbox);UI.appendChild(document.createTextNode(" "));const startBtn=document.createElement("button");startBtn.textContent="Start";UI.appendChild(startBtn);const nextBtn=document.createElement("button");nextBtn.textContent="Next";nextBtn.disabled=true;UI.appendChild(nextBtn);UI.appendChild(document.createTextNode(" "));const scrambleSelect=document.createElement("select");["Random","Reverse","Nearly Sorted"].forEach(p=>{const o=document.createElement("option");o.value=p;o.textContent=p;scrambleSelect.appendChild(o);});UI.appendChild(scrambleSelect);const scrambleBtn=document.createElement("button");scrambleBtn.textContent="Scramble";UI.appendChild(scrambleBtn);UI.appendChild(document.createElement("br"));const statsDiv=document.createElement("div");statsDiv.style.fontFamily="monospace";UI.appendChild(statsDiv);const arrSize=100;let array=[];let colors=[];let maxVal=arrSize;let sorting=false;let comparisons=0;let swaps=0;let callDepth=0;let currentRange=null;function initArray(){array=Array.from({length:arrSize},(_,i)=>i+1);colors=new Array(arrSize).fill("#777");render();}function render(){ctx.clearRect(0,0,canvas.width,canvas.height);const barW=canvas.width/arrSize;for(let i=0;i<arrSize;i++){const val=array[i];const h=val/maxVal*canvas.height;const x=i*barW;ctx.fillStyle=colors[i];ctx.fillRect(x,canvas.height-h,barW, h);}if(currentRange){ctx.fillStyle="rgba(0,0,255,0.1)";ctx.fillRect(currentRange[0]*barW,0,(currentRange[1]-currentRange[0]+1)*barW,canvas.height);}statsDiv.innerHTML=`Complexity: ${algoComplexity[algoSelect.value]} | Comparisons: ${comparisons} | Swaps: ${swaps} | Call depth: ${callDepth}`;}function setBarColor(i,c){colors[i]=c;}function resetColors(){colors.fill("#777");}function sleep(ms){return new Promise(r=>setTimeout(r,ms));}function waitStep(){return new Promise(r=>{nextBtn.disabled=false;nextBtn.onclick=()=>{nextBtn.disabled=true;nextBtn.onclick=null;r();};});}async function pause(){if(stepCheckbox.checked){await waitStep();}else{await sleep(speedSlider.value);} }function scramble(pattern){switch(pattern){case"Random":for(let i=array.length-1;i>0;i--){let j=Math.floor(Math.random()* (i+1));[array[i],array[j]]=[array[j],array[i]];}break;case"Reverse":array=array.slice().reverse();break;case"Nearly Sorted":array=Array.from({length:arrSize},(_,i)=>i+1);for(let i=0;i<Math.floor(arrSize*0.05);i++){let a=Math.floor(Math.random()*arrSize);let b=Math.floor(Math.random()*arrSize);[array[a],array[b]]=[array[b],array[a]];}break;}resetColors();render();}const algoComplexity={Bubble:"O(n²)",Quick:"O(n log n)",Merge:"O(n log n)",Heap:"O(n log n)",Radix:"O(nk)"};async function bubbleSort(){for(let i=0;i<arrSize-1;i++){for(let j=0;j<arrSize-i-1;j++){setBarColor(j,"red");setBarColor(j+1,"red");render();await pause();comparisons++;if(array[j]>array[j+1]){setBarColor(j,"yellow");setBarColor(j+1,"yellow");render();await pause();[array[j],array[j+1]]=[array[j+1],array[j]];swaps++;}}setBarColor(arrSize-i-1,"green");}for(let i=0;i<arrSize;i++)setBarColor(i,"green");render();}async function quickSort(l,r,depth){if(l<r){callDepth=Math.max(callDepth,depth);setBarColor(r,"blue");render();await pause();let pivot=array[r];let i=l-1;for(let j=l;j<r;j++){setBarColor(j,"red");setBarColor(i+1,"red");render();await pause();comparisons++;if(array[j]<=pivot){i++;[array[i],array[j]]=[array[j],array[i]];swaps++;setBarColor(i,"yellow");setBarColor(j,"yellow");render();await pause();}}[array[i+1],array[r]]=[array[r],array[i+1]];swaps++;setBarColor(i+1,"green");render();await pause();await quickSort(l,i,depth+1);await quickSort(i+2,r,depth+1);}else if(l===r){setBarColor(l,"green");}}async function mergeSort(l,r,depth){if(l<r){callDepth=Math.max(callDepth,depth);const m=Math.floor((l+r)/2);await mergeSort(l,m,depth+1);await mergeSort(m+1,r,depth+1);let left=array.slice(l,m+1);let right=array.slice(m+1,r+1);let i=0,j=0,k=l;while(i<left.length && j<right.length){setBarColor(k,"red");render();await pause();comparisons++;if(left[i]<=right[j]){array[k]=left[i++];swaps++;}else{array[k]=right[j++];swaps++;}setBarColor(k,"yellow");render();await pause();k++;}while(i<left.length){setBarColor(k,"red");render();await pause();array[k]=left[i++];swaps++;setBarColor(k,"yellow");render();await pause();k++;}while(j<right.length){setBarColor(k,"red");render();await pause();array[k]=right[j++];swaps++;setBarColor(k,"yellow");render();await pause();k++;}}else if(l===r){setBarColor(l,"green");}}async function heapSort(){function heapify(n,i){let largest=i;let l=2*i+1;let r=2*i+2;if(l<n){setBarColor(l,"red");render();await pause();comparisons++;if(array[l]>array[largest])largest=l;}if(r<n){setBarColor(r,"red");render();await pause();comparisons++;if(array[r]>array[largest])largest=r;}if(largest!==i){setBarColor(i,"yellow");setBarColor(largest,"yellow");render();await pause();[array[i],array[largest]]=[array[largest],array[i]];swaps++;await heapify(n,largest);} } for(let i=Math.floor(arrSize/2)-1;i>=0;i--){await heapify(arrSize,i);} for(let i=arrSize-1;i>0;i--){setBarColor(0,"yellow");setBarColor(i,"yellow");render();await pause();[array[0],array[i]]=[array[i],array[0]];swaps++;await heapify(i,0);} setBarColor(0,"green");render();}async function radixSort(){let max=Math.max(...array);let exp=1;while(Math.floor(max/exp)>0){let output=new Array(arrSize);let count=new Array(10).fill(0);for(let i=0;i<arrSize;i++){let idx=Math.floor(array[i]/exp)%10;count[idx]++;}for(let i=1;i<10;i++)count[i]+=count[i-1];for(let i=arrSize-1;i>=0;i--){let idx=Math.floor(array[i]/exp)%10;output[--count[idx]]=array[i];swaps++;}for(let i=0;i<arrSize;i++){array[i]=output[i];setBarColor(i,"yellow");render();await pause();}exp*=10;} for(let i=0;i<arrSize;i++)setBarColor(i,"green");render();}async function runAlgorithm(){sorting=true;resetColors();comparisons=0;swaps=0;callDepth=0;currentRange=null;render();switch(algoSelect.value){case"Bubble":await bubbleSort();break;case"Quick":await quickSort(0,arrSize-1,1);break;case"Merge":await mergeSort(0,arrSize-1,1);break;case"Heap":await heapSort();break;case"Radix":await radixSort();break;}sorting=false;nextBtn.disabled=true;}speedSlider.oninput=()=>{speedLabel.textContent=`${speedSlider.value}ms`};scrambleBtn.onclick=()=>scramble(scrambleSelect.value);startBtn.onclick={if(sorting)return;runAlgorithm();};initArray();}

